//! Raw bindings, generated by `build.rs` from the headers of the libraries
//! pm-media links: Powermove's FFmpeg build, dav1d, and OpenEXRCore.
#![allow(
    non_upper_case_globals,
    non_camel_case_types,
    non_snake_case,
    dead_code,
    unused_imports,
    unnecessary_transmutes,
    clippy::all
)]

pub mod ffmpeg {
    include!(concat!(env!("OUT_DIR"), "/ffmpeg.rs"));

    /// `AV_NOPTS_VALUE` (a cast macro bindgen cannot evaluate).
    pub const AV_NOPTS_VALUE: i64 = i64::MIN;
    /// `AVERROR(e)` for POSIX error numbers.
    pub const fn averror(e: i32) -> i32 {
        -e
    }
    const fn fferrtag(a: u8, b: u8, c: u8, d: u8) -> i32 {
        -((a as i32) | ((b as i32) << 8) | ((c as i32) << 16) | ((d as i32) << 24))
    }
    /// `AVERROR_EOF`.
    pub const AVERROR_EOF: i32 = fferrtag(b'E', b'O', b'F', b' ');
    /// `AVERROR_INVALIDDATA`.
    pub const AVERROR_INVALIDDATA: i32 = fferrtag(b'I', b'N', b'D', b'A');
    /// `AV_TIME_BASE_Q`.
    pub const AV_TIME_BASE_Q: AVRational = AVRational {
        num: 1,
        den: AV_TIME_BASE as i32,
    };
}

pub mod dav1d {
    include!(concat!(env!("OUT_DIR"), "/dav1d.rs"));
}

pub mod openexr {
    include!(concat!(env!("OUT_DIR"), "/openexr.rs"));
}
